// pubspec.yaml:
//   firebase_performance: ^0.9.3+8

import 'package:firebase_performance/firebase_performance.dart';

final perf = FirebasePerformance.instance;

// 1. Global on/off (respect user consent — same pattern as Analytics/Crashlytics).
await perf.setPerformanceCollectionEnabled(userConsent.telemetry);

// ────── Custom trace ──────
final trace = perf.newTrace('checkout');
await trace.start();
trace.putAttribute('payment_method', 'card');   // string attribute — sliceable in console
trace.putAttribute('tenant', tenantId);
trace.setMetric('items_in_cart', cart.length); // numeric metric — aggregated + averaged

try {
  await runCheckoutFlow();
} finally {
  await trace.stop();
}

// ────── HTTP metric — one-off timing for a request you control ──────
final metric = perf.newHttpMetric('https://api.example.com/orders', HttpMethod.Post);
await metric.start();
final resp = await http.post(url, body: body);
metric.responseCode = resp.statusCode;
metric.responsePayloadSize = resp.contentLength ?? 0;
await metric.stop();

// ────── Screen trace (Flutter — auto via widget) ──────
// The plugin ships a `withPerformanceOverlay` widget that auto-emits screen traces.
// Also available via a route observer on newer plugin versions.

// ────── Debugging locally ──────
// Console → Performance → 'DebugView' shows real-time traces from the connected device.
// Ensure enough sessions have occurred (~12 h in prod).
